package io.kyil.osrsbanksync;

import net.runelite.api.vars.AccountType;

final class AccountTypeMapper
{
    private AccountTypeMapper()
    {
    }

    /** Returns the wire string, or null if the input is null. */
    static String toWire(AccountType type)
    {
        if (type == null)
        {
            return null;
        }

        switch (type)
        {
            case NORMAL:
                return "NORMAL";
            case IRONMAN:
                return "IRONMAN";
            case ULTIMATE_IRONMAN:
                return "ULTIMATE_IRONMAN";
            case HARDCORE_IRONMAN:
                return "HARDCORE_IRONMAN";
            case GROUP_IRONMAN:
                return "GROUP_IRONMAN";
            case HARDCORE_GROUP_IRONMAN:
                return "HARDCORE_GROUP_IRONMAN";
            default:
                return null; // future-proof against new enum values
        }
    }
}

package io.kyil.osrsbanksync;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;

@Singleton
public class BankCaptureService
{
    static final String PLUGIN_VERSION = "0.1.0";

    private final Client client;

    @Inject
    public BankCaptureService(Client client)
    {
        this.client = client;
    }

    public BankSnapshot captureNow()
    {
        ItemContainer container = client.getItemContainer(InventoryID.BANK);
        if (container == null)
        {
            return null;
        }

        return captureFrom(container);
    }

    public BankSnapshot captureFrom(ItemContainer container)
    {
        List<BankItem> capturedItems = new ArrayList<>();
        Item[] items = container.getItems();
        if (items != null)
        {
            for (int slot = 0; slot < items.length; slot++)
            {
                Item item = items[slot];
                if (item == null)
                {
                    continue;
                }

                int itemId = item.getId();
                int quantity = item.getQuantity();
                if (itemId <= 0 || quantity == 0)
                {
                    continue;
                }

                capturedItems.add(new BankItem(slot, itemId, quantity));
            }
        }

        Player localPlayer = client.getLocalPlayer();
        String displayName = localPlayer != null ? localPlayer.getName() : null;

        return new BankSnapshot(
            client.getAccountHash(),
            displayName,
            AccountTypeMapper.toWire(client.getAccountType()),
            Instant.now().truncatedTo(ChronoUnit.SECONDS).toString(),
            PLUGIN_VERSION,
            UUID.randomUUID().toString(),
            Collections.unmodifiableList(capturedItems)
        );
    }
}

package io.kyil.osrsbanksync;

public final class BankItem
{
    private final int slot;
    private final int itemId;
    private final int quantity;

    public BankItem(int slot, int itemId, int quantity)
    {
        this.slot = slot;
        this.itemId = itemId;
        this.quantity = quantity;
    }

    public int getSlot()
    {
        return slot;
    }

    public int getItemId()
    {
        return itemId;
    }

    public int getQuantity()
    {
        return quantity;
    }
}

package io.kyil.osrsbanksync;

import java.util.List;

public final class BankSnapshot
{
    private final long accountHash;
    private final String displayName;
    private final String accountType;
    private final String capturedAt;
    private final String pluginVersion;
    private final String snapshotId;
    private final List<BankItem> items;

    public BankSnapshot(
        long accountHash,
        String displayName,
        String accountType,
        String capturedAt,
        String pluginVersion,
        String snapshotId,
        List<BankItem> items
    )
    {
        this.accountHash = accountHash;
        this.displayName = displayName;
        this.accountType = accountType;
        this.capturedAt = capturedAt;
        this.pluginVersion = pluginVersion;
        this.snapshotId = snapshotId;
        this.items = items;
    }

    public long getAccountHash()
    {
        return accountHash;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public String getAccountType()
    {
        return accountType;
    }

    public String getCapturedAt()
    {
        return capturedAt;
    }

    public String getPluginVersion()
    {
        return pluginVersion;
    }

    public String getSnapshotId()
    {
        return snapshotId;
    }

    public List<BankItem> getItems()
    {
        return items;
    }
}

package io.kyil.osrsbanksync;

import com.google.gson.FieldNamingPolicy;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
@Singleton
public class BankSubmitter
{
    private static final String USER_AGENT = "osrs-bank-sync/0.1.0 (+https://github.com/kyleamielke/osrs-bank-sync)";
    private static final int LOG_RESPONSE_BODY_LIMIT = 200;
    private static final MediaType JSON_UTF8 = MediaType.parse("application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    private final Gson wireGson;
    private final OsrsBankSyncConfig config;
    private final AtomicReference<String> lastWarnedPlaintextUrl = new AtomicReference<>();
    private String lastSubmittedPayloadHash;

    @Inject
    public BankSubmitter(OkHttpClient okHttpClient, Gson gson, OsrsBankSyncConfig config)
    {
        this.httpClient = okHttpClient.newBuilder()
            .connectTimeout(3, TimeUnit.SECONDS)
            .writeTimeout(5, TimeUnit.SECONDS)
            .readTimeout(5, TimeUnit.SECONDS)
            .callTimeout(10, TimeUnit.SECONDS)
            .build();
        this.wireGson = gson.newBuilder()
            .setFieldNamingPolicy(FieldNamingPolicy.LOWER_CASE_WITH_UNDERSCORES)
            .serializeNulls()
            .create();
        this.config = config;
    }

    public SubmitResult submit(BankSnapshot snapshot, boolean force)
    {
        if (snapshot == null)
        {
            return new SubmitResult(SubmitResult.Outcome.NOT_ATTEMPTED, 0, "");
        }

        String baseUrl = config.targetUrl();
        HttpUrl target = buildTargetUrl(baseUrl);
        if (target == null)
        {
            return new SubmitResult(SubmitResult.Outcome.NOT_ATTEMPTED, 0, "");
        }

        if (shouldWarnPlaintextNonLoopback(target) && baseUrl != null
            && !baseUrl.equals(lastWarnedPlaintextUrl.getAndSet(baseUrl)))
        {
            log.warn("Bank sync is sending data over plaintext HTTP to a non-loopback host: {}", target.host());
            // TODO(4.3): emit the same warning to chat once per URL.
        }

        String payloadHash = payloadHashForDedupe(snapshot);
        if (!force && payloadHash.equals(lastSubmittedPayloadHash))
        {
            return new SubmitResult(SubmitResult.Outcome.SKIPPED_DEDUPE, 0, "");
        }

        String payloadJson = wireGson.toJson(snapshot);
        Request.Builder requestBuilder = new Request.Builder()
            .url(target)
            .header("Content-Type", "application/json; charset=utf-8")
            .header("User-Agent", USER_AGENT)
            .post(RequestBody.create(JSON_UTF8, payloadJson));
        String token = config.authToken();
        if (token != null && !token.isEmpty())
        {
            requestBuilder.header("Authorization", "Bearer " + token);
        }

        Request request = requestBuilder.build();
        log.debug("Sending bank sync request with headers: {}", request.headers().names());

        try (Response response = httpClient.newCall(request).execute())
        {
            int code = response.code();
            String responseBody = readTruncatedBody(response.body());
            log.info("Bank submit response status={} body={}", code, responseBody);

            if (code == 200 || code == 204)
            {
                lastSubmittedPayloadHash = payloadHash;
                return new SubmitResult(SubmitResult.Outcome.SENT_OK, code, "");
            }
            if (code >= 400 && code <= 499)
            {
                return new SubmitResult(SubmitResult.Outcome.SENT_REJECTED_TERMINAL, code, responseBody);
            }
            if (code >= 500 && code <= 599)
            {
                return new SubmitResult(SubmitResult.Outcome.SENT_TRANSIENT_FAIL, code, "");
            }
            return new SubmitResult(SubmitResult.Outcome.SENT_TRANSIENT_FAIL, code, "");
        }
        catch (IOException e)
        {
            log.warn("Bank submit failed with IO exception", e);
            return new SubmitResult(SubmitResult.Outcome.SENT_TRANSIENT_FAIL, 0, "");
        }
    }

    String payloadHashForDedupe(BankSnapshot snapshot)
    {
        JsonObject payload = wireGson.toJsonTree(snapshot).getAsJsonObject();
        payload.remove("snapshot_id");
        payload.remove("captured_at");
        return sha256Hex(wireGson.toJson(payload));
    }

    static boolean shouldWarnPlaintextNonLoopback(HttpUrl url)
    {
        if (url == null || !"http".equals(url.scheme()))
        {
            return false;
        }

        String host = url.host();
        return !"127.0.0.1".equals(host) && !"localhost".equals(host) && !"::1".equals(host);
    }

    private static HttpUrl buildTargetUrl(String baseUrl)
    {
        if (baseUrl == null)
        {
            return null;
        }

        HttpUrl base = HttpUrl.parse(baseUrl);
        if (base == null)
        {
            return null;
        }

        return base.newBuilder()
            .addPathSegments("api/v1/sync/bank")
            .build();
    }

    private static String readTruncatedBody(ResponseBody responseBody) throws IOException
    {
        if (responseBody == null)
        {
            return "";
        }

        String body = responseBody.string();
        return StringUtils.truncate(body, LOG_RESPONSE_BODY_LIMIT);
    }

    private static String sha256Hex(String value)
    {
        MessageDigest digest = sha256Digest();
        byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));
        return toHex(hash);
    }

    private static MessageDigest sha256Digest()
    {
        try
        {
            return MessageDigest.getInstance("SHA-256");
        }
        catch (NoSuchAlgorithmException e)
        {
            throw new IllegalStateException("SHA-256 is not available", e);
        }
    }

    private static String toHex(byte[] bytes)
    {
        StringBuilder out = new StringBuilder(bytes.length * 2);
        for (byte value : bytes)
        {
            out.append(Character.forDigit((value >> 4) & 0xF, 16));
            out.append(Character.forDigit(value & 0xF, 16));
        }
        return out.toString();
    }
}

package io.kyil.osrsbanksync;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
class BankSyncButton
{
    private static final String BUTTON_NAME = "osrsbanksync-sync-button";
    private static final String BUTTON_TEXT = "Sync";
    private static final String INVALID_URL_MESSAGE =
        "Bank Sync: target URL must not contain user:pass@ or ?query — refusing to submit until fixed.";

    private final Client client;
    private final ClientThread clientThread;
    private final BankCaptureService captureService;
    private final BankSubmitter submitter;
    private final OsrsBankSyncConfig config;

    @Inject
    BankSyncButton(
        Client client,
        ClientThread clientThread,
        BankCaptureService captureService,
        BankSubmitter submitter,
        OsrsBankSyncConfig config)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.captureService = captureService;
        this.submitter = submitter;
        this.config = config;
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() != InterfaceID.BANKMAIN)
        {
            return;
        }

        clientThread.invokeLater(this::addButtonIfMissing);
    }

    private void addButtonIfMissing()
    {
        Widget titleBar = client.getWidget(InterfaceID.Bankmain.TITLE);
        Widget searchButton = client.getWidget(InterfaceID.Bankmain.SEARCH);
        if (titleBar == null || searchButton == null)
        {
            return;
        }

        if (findButton(titleBar) != null)
        {
            return;
        }

        int width = 40;
        int height = searchButton.getOriginalHeight();
        int x = searchButton.getOriginalX() - width - 4;
        int y = searchButton.getOriginalY();

        Widget button = titleBar.createChild(-1, WidgetType.TEXT)
            .setName(BUTTON_NAME)
            .setText(BUTTON_TEXT)
            .setTextColor(0xFFFFFF)
            .setTextShadowed(true)
            .setFontId(FontID.PLAIN_11)
            .setXTextAlignment(WidgetTextAlignment.CENTER)
            .setYTextAlignment(WidgetTextAlignment.CENTER)
            .setPos(x, y)
            .setSize(width, height)
            .setXPositionMode(searchButton.getXPositionMode())
            .setYPositionMode(searchButton.getYPositionMode())
            .setHasListener(true);

        button.setAction(0, "Sync bank now");
        button.setOnOpListener((JavaScriptCallback) e -> onButtonClick());
        button.revalidate();
    }

    private Widget findButton(Widget parent)
    {
        Widget[] children = parent.getChildren();
        if (children == null)
        {
            return null;
        }

        for (Widget child : children)
        {
            if (child != null && BUTTON_NAME.equals(child.getName()))
            {
                return child;
            }
        }
        return null;
    }

    private void onButtonClick()
    {
        if (config.submitMode() == OsrsBankSyncConfig.SubmitMode.OFF || !config.includeBank())
        {
            return;
        }

        if (!TargetUrlValidator.isValid(config.targetUrl()))
        {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", INVALID_URL_MESSAGE, null);
            return;
        }

        BankSnapshot snapshot = captureService.captureNow();
        if (snapshot == null)
        {
            log.debug("Sync button clicked but no snapshot was available");
            return;
        }

        submitter.submit(snapshot, true);
    }
}

package io.kyil.osrsbanksync;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("osrsbanksync")
public interface OsrsBankSyncConfig extends Config
{
    @ConfigItem(
        keyName = "targetUrl",
        name = "Target URL",
        position = 0,
        description = "Base URL of the receiver. POSTs go to {targetUrl}/api/v1/sync/bank."
    )
    default String targetUrl()
    {
        return "http://127.0.0.1:8484";
    }

    @ConfigItem(
        keyName = "authToken",
        name = "Auth token",
        position = 1,
        secret = true,
        description = "Sent as Authorization: Bearer <token>. Leave empty to disable. "
            + "Token is opaque — static key, OAuth, or JWT all work."
    )
    default String authToken()
    {
        return "";
    }

    @ConfigItem(
        keyName = "submitMode",
        name = "Submit mode",
        position = 2,
        description = "When to submit bank snapshots."
    )
    default SubmitMode submitMode()
    {
        return SubmitMode.AUTO_ON_CLOSE;
    }

    @ConfigItem(
        keyName = "includeBank",
        name = "Sync bank",
        position = 3,
        description = "Capture and submit bank contents. Reserved for future include flags."
    )
    default boolean includeBank()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showChatConfirmations",
        name = "Show chat confirmations",
        position = 4,
        description = "Print a chat message on each successful submission."
    )
    default boolean showChatConfirmations()
    {
        return true;
    }

    enum SubmitMode
    {
        AUTO_ON_CLOSE,
        MANUAL_ONLY,
        OFF
    }
}

package io.kyil.osrsbanksync;

import com.google.inject.Provides;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
    name = "OSRS Bank Sync",
    description = "Sync your bank contents to a self-hosted endpoint (e.g. osrs-tracker)",
    tags = {"bank", "sync", "tracker", "wealth"}
)
public class OsrsBankSyncPlugin extends Plugin
{
    private final AtomicBoolean dirty = new AtomicBoolean(false);
    private static final String CONFIG_GROUP = "osrsbanksync";
    private static final String TARGET_URL_KEY = "targetUrl";
    private static final String INVALID_URL_MESSAGE =
        "Bank Sync: target URL must not contain user:pass@ or ?query — refusing to submit until fixed.";
    private static final String PLAINTEXT_WARNING_MESSAGE =
        "Bank sync is sending data over plaintext HTTP to a non-loopback host.";

    private volatile BankSnapshot lastCapturedSnapshot;
    private volatile boolean configValid = true;
    private final AtomicReference<String> lastChatWarnedPlaintextUrl = new AtomicReference<>();

    @Inject
    private Client client;

    @Inject
    private OsrsBankSyncConfig config;

    @Inject
    private BankCaptureService captureService;

    @Inject
    private BankSubmitter submitter;

    @Inject
    private BankSyncButton bankSyncButton;

    @Inject
    private EventBus eventBus;

    @Override
    protected void startUp() throws Exception
    {
        dirty.set(false);
        lastCapturedSnapshot = null;
        lastChatWarnedPlaintextUrl.set(null);
        configValid = validateTargetUrl(config.targetUrl());
        eventBus.register(bankSyncButton);
        if (!configValid)
        {
            log.warn(INVALID_URL_MESSAGE);
        }
        log.info("OSRS Bank Sync started");
    }

    @Override
    protected void shutDown() throws Exception
    {
        dirty.set(false);
        lastCapturedSnapshot = null;
        lastChatWarnedPlaintextUrl.set(null);
        eventBus.unregister(bankSyncButton);
        log.info("OSRS Bank Sync stopped");
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.BANK.getId())
        {
            return;
        }

        lastCapturedSnapshot = captureService.captureFrom(event.getItemContainer());
        dirty.set(true);
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        if (event.getGroupId() != InterfaceID.BANKMAIN || !event.isUnload())
        {
            return;
        }

        if (!configValid || !config.includeBank() || config.submitMode() == OsrsBankSyncConfig.SubmitMode.OFF)
        {
            return;
        }

        if (config.submitMode() == OsrsBankSyncConfig.SubmitMode.MANUAL_ONLY)
        {
            return;
        }

        if (!dirty.get())
        {
            return;
        }

        if (client.getGameState() != GameState.LOGGED_IN || client.getAccountHash() == -1L)
        {
            return;
        }

        BankSnapshot snapshot = captureService.captureNow();
        if (snapshot == null)
        {
            return;
        }

        lastCapturedSnapshot = snapshot;
        maybeWarnPlaintextNonLoopbackInChat();
        handleSubmitResult(submitter.submit(snapshot, false));
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState gameState = event.getGameState();
        if (gameState != GameState.HOPPING
            && gameState != GameState.CONNECTION_LOST
            && gameState != GameState.LOGIN_SCREEN)
        {
            return;
        }

        if (!configValid || !config.includeBank() || config.submitMode() == OsrsBankSyncConfig.SubmitMode.OFF)
        {
            return;
        }

        if (config.submitMode() == OsrsBankSyncConfig.SubmitMode.MANUAL_ONLY)
        {
            return;
        }

        if (!dirty.get() || lastCapturedSnapshot == null)
        {
            return;
        }

        maybeWarnPlaintextNonLoopbackInChat();
        handleSubmitResult(submitter.submit(lastCapturedSnapshot, false));
    }

    private void handleSubmitResult(SubmitResult result)
    {
        if (result.getOutcome() == SubmitResult.Outcome.SENT_OK
            || result.getOutcome() == SubmitResult.Outcome.SENT_REJECTED_TERMINAL)
        {
            dirty.set(false);
        }

        switch (result.getOutcome())
        {
            case SENT_OK:
                if (config.showChatConfirmations())
                {
                    client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Bank synced.", null);
                }
                break;
            case SENT_REJECTED_TERMINAL:
                if (result.getHttpCode() == 401)
                {
                    client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                        "Bank sync auth failed — check token in config.", null);
                }
                else if (config.showChatConfirmations())
                {
                    String chat = "Bank sync rejected: " + StringUtils.truncate(result.getResponseBody(), 80);
                    client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", chat, null);
                }
                break;
            default:
                break;
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!CONFIG_GROUP.equals(event.getGroup()) || !TARGET_URL_KEY.equals(event.getKey()))
        {
            return;
        }

        configValid = validateTargetUrl(config.targetUrl());
        if (!configValid)
        {
            log.warn(INVALID_URL_MESSAGE);
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", INVALID_URL_MESSAGE, null);
        }
    }

    private boolean validateTargetUrl(String raw)
    {
        return TargetUrlValidator.isValid(raw);
    }

    private void maybeWarnPlaintextNonLoopbackInChat()
    {
        String targetUrl = config.targetUrl();
        if (targetUrl == null)
        {
            return;
        }

        okhttp3.HttpUrl parsed = okhttp3.HttpUrl.parse(targetUrl);
        if (!BankSubmitter.shouldWarnPlaintextNonLoopback(parsed))
        {
            return;
        }

        if (!targetUrl.equals(lastChatWarnedPlaintextUrl.getAndSet(targetUrl)))
        {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", PLAINTEXT_WARNING_MESSAGE, null);
        }
    }

    @Provides
    OsrsBankSyncConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(OsrsBankSyncConfig.class);
    }
}

package io.kyil.osrsbanksync;

final class StringUtils
{
    private StringUtils()
    {
    }

    static String truncate(String value, int maxLen)
    {
        if (value == null || value.isEmpty() || maxLen <= 0)
        {
            return "";
        }

        if (value.length() <= maxLen)
        {
            return value;
        }

        return value.substring(0, maxLen);
    }
}

package io.kyil.osrsbanksync;

public final class SubmitResult
{
    public enum Outcome
    {
        SENT_OK,
        SENT_REJECTED_TERMINAL,
        SENT_TRANSIENT_FAIL,
        SKIPPED_DEDUPE,
        NOT_ATTEMPTED
    }

    private final Outcome outcome;
    private final int httpCode;
    private final String responseBody;

    public SubmitResult(Outcome outcome, int httpCode, String responseBody)
    {
        this.outcome = outcome;
        this.httpCode = httpCode;
        this.responseBody = responseBody == null ? "" : responseBody;
    }

    public Outcome getOutcome()
    {
        return outcome;
    }

    public int getHttpCode()
    {
        return httpCode;
    }

    public String getResponseBody()
    {
        return responseBody;
    }
}

package io.kyil.osrsbanksync;

import okhttp3.HttpUrl;

final class TargetUrlValidator
{
    private TargetUrlValidator()
    {
    }

    static boolean isValid(String raw)
    {
        if (raw == null || raw.isEmpty())
        {
            return false;
        }

        HttpUrl url = HttpUrl.parse(raw);
        if (url == null)
        {
            return false;
        }

        if (!url.username().isEmpty())
        {
            return false;
        }

        if (!url.password().isEmpty())
        {
            return false;
        }

        return url.querySize() == 0;
    }
}

